mapper.select:
SELECT COUNT(*) FROM customer_info t
WHERE t.customer_type = 2

    AND t.tenant_id = #{ctx.tenantId}

SELECT COUNT(*) FROM customer_log t
WHERE t.log_type = 5
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

SELECT COUNT(*) FROM customer_log t
WHERE t.log_type = 6
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

SELECT COUNT(*) FROM customer_log t
WHERE t.log_type = 7
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

SELECT COUNT(*) FROM customer_info t
WHERE t.customer_type = 2

    AND t.tenant_id = #{ctx.tenantId}

SELECT COALESCE(ROUND(AVG(TIMESTAMPDIFF(HOUR, cl_in.create_time, cl_in.next_reclaim) / 24.0), 2), 0)
FROM (
    SELECT
        cl_in.customer_id,
        cl_in.create_time,
        (SELECT MIN(cl_out.create_time)
         FROM customer_log cl_out
         WHERE cl_out.customer_id = cl_in.customer_id
           AND cl_out.log_type IN (6, 7)
           AND cl_out.create_time > cl_in.create_time
        ) AS next_reclaim
    FROM customer_log cl_in
    WHERE cl_in.log_type = 5
      AND cl_in.create_time >= #{start}
      AND cl_in.create_time <= #{end}

      AND cl_in.tenant_id = #{ctx.tenantId}


      AND cl_in.create_by IN
      #{u}

) AS cl_in
WHERE cl_in.next_reclaim IS NOT NULL
